      } else if (f.type === 'not') {
        list = list.filter(r => r[f.col] !== f.val);
      } else if (f.type === 'is') {
        list = list.filter(r => r[f.col] === null);
      }
    });
    return list;
  };

  return {
    select: () => ({
      eq: (col, val) => {
        filters.push({ type: 'eq', col, val });
        return builderOps();
      },
      gte: (col, val) => {
        filters.push({ type: 'gte', col, val });
        return builderOps();
      },
      lte: (col, val) => {
        filters.push({ type: 'lte', col, val });
        return builderOps();
      },
      not: (col, val) => {
        filters.push({ type: 'not', col, val });
        return builderOps();
      },
      is: (col, val) => {
        filters.push({ type: 'is', col, val });
        return builderOps();
      },
      order: (col, { ascending = true } = {}) => {
        const list = applyFilters();
        list.sort((a, b) => (a[col] > b[col] ? 1 : -1) * (ascending ? 1 : -1));
        return {
          limit: (n) => Promise.resolve({ data: list.slice(0, n), error: null })
        };
      }
    }),
    insert: async (data) => {
      const arr = Array.isArray(data) ? data : [data];
      const newRows = arr.map(d => ({ id: generateID(), ...d }));
      saveTable(tableName, [...rows, ...newRows]);
      return { data: newRows, error: null };
    },
    update: async (data) => ({
      eq: (col, val) => {
        const updated = rows.map(r => r[col] === val ? { ...r, ...data } : r);
        saveTable(tableName, updated);
        return { error: null };
      },
